diff --git a/src/core/project.ts b/src/core/project.ts
index 76d1577..eb724d4 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,50 @@ export interface Record {
   warns: readonly string[];
 }

+const deduplicateByCluster = (entries: readonly string[]): string[] => {
+  if (entries.length === 0) return [];
+
+  const clusters: Map<number, string[]> = new Map();
+
+  for (const entry of entries) {
+    const normalized = entry.toLowerCase();
+    const keywords = new Set(normalized.split(/\s+/).filter(w => w.length > 3));
+
+    let bestCluster = -1;
+    let bestOverlap = 0;
+
+    for (const [clusterId, clusterEntries] of clusters) {
+      const clusterKeywords = new Set(clusterEntries[0].toLowerCase().split(/\s+/).filter(w => w.length > 3));
+      const overlap = [...keywords].filter(k => clusterKeywords.has(k)).length;
+      if (overlap > bestOverlap && overlap >= 2) {
+        bestOverlap = overlap;
+        bestCluster = clusterId;
+      }
+    }
+
+    if (bestCluster === -1) {
+      bestCluster = clusters.size;
+    }
+
+    if (!clusters.has(bestCluster)) {
+      clusters.set(bestCluster, []);
+    }
+    clusters.get(bestCluster)!.push(entry);
+  }
+
+  const deduped: string[] = [];
+  for (const clusterEntries of clusters.values()) {
+    deduped.push(clusterEntries[0]);
+  }
+  return deduped;
+};
+
 export const project = (records: readonly Record[]): string => {
   const lines: string[] = [];
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    for (const entry of deduplicateByCluster(record.ruledOut)) lines.push(`- ruled out: ${entry}`);
+    for (const limit of deduplicateByCluster(record.limits)) lines.push(`- limit: ${limit}`);
+    for (const warn of deduplicateByCluster(record.warns)) lines.push(`- warn: ${warn}`);
   }
   return lines.join("\n");
 };
